import{_ as a,o as i,c as t,ak as s}from"./chunks/framework.Dr_OVAaJ.js";const n="/projects/JetHexa/en/latest/assets/image1.C6-fOXe5.webp",o="/projects/JetHexa/en/latest/assets/image1.BHCco_m7.webp",r="/projects/JetHexa/en/latest/assets/image2.BH7YdEtB.webp",l="/projects/JetHexa/en/latest/assets/image3.B7EwlaKI.webp",h="/projects/JetHexa/en/latest/assets/image1.pw0pcKZG.webp",d="/projects/JetHexa/en/latest/assets/image2.C-rwCXpd.webp",p="data:image/png;base64,",g="/projects/JetHexa/en/latest/assets/image1.pw0pcKZG.webp",c="/projects/JetHexa/en/latest/assets/image2.BQR2-WOA.webp",A="data:image/png;base64,",m="/projects/JetHexa/en/latest/assets/image1.pw0pcKZG.webp",k="/projects/JetHexa/en/latest/assets/image2.CjT9bvt3.webp",u="data:image/png;base64,",D=JSON.parse('{"title":"3. LiDAR Course","description":"","frontmatter":{},"headers":[],"relativePath":"docs/3. LiDAR Course.md","filePath":"docs/3. LiDAR Course.md"}'),f={name:"docs/3. LiDAR Course.md"};function b(C,e,F,v,y,E){return i(),t("div",null,[...e[0]||(e[0]=[s('<h1 id="_3-lidar-course" tabindex="-1">3. LiDAR Course <a class="header-anchor" href="#_3-lidar-course" aria-label="Permalink to &quot;3. LiDAR Course&quot;">​</a></h1><h2 id="_3-1-lidar-introduction" tabindex="-1">3.1 LiDAR Introduction <a class="header-anchor" href="#_3-1-lidar-introduction" aria-label="Permalink to &quot;3.1 LiDAR Introduction&quot;">​</a></h2><h3 id="_3-1-1-overview" tabindex="-1">3.1.1 Overview <a class="header-anchor" href="#_3-1-1-overview" aria-label="Permalink to &quot;3.1.1 Overview&quot;">​</a></h3><p>As a high-precision, high-rate remote sensing technology, LiDAR plays an essential role in mapping, autonomous driving, environmental perception, and robot navigation. This section introduces the principles, components, operating mechanisms, application fields, and advantages of LiDAR, as well as its future development trends.</p><p>LiDAR plays a key role in autonomous driving and intelligent transportation, perceiving obstacles, pedestrians, and vehicles on the road in real time while providing precise distance and position information. In robot navigation and environmental perception, LiDAR provides robots with accurate maps and surrounding environmental information. In addition, LiDAR is widely used in 3D modeling and mapping, safety monitoring, remote sensing, and surveying.</p><img loading="lazy" height="330" width="611" src="'+n+'" class="common_img" style="width:800px;"><h3 id="_3-1-2-lidar-composition-and-classification" tabindex="-1">3.1.2 LiDAR Composition and Classification <a class="header-anchor" href="#_3-1-2-lidar-composition-and-classification" aria-label="Permalink to &quot;3.1.2 LiDAR Composition and Classification&quot;">​</a></h3><p>LiDAR consists of components such as a laser emitter, a receiver, a photodetector, a scanning mechanism, and an angle resolver. The laser emitter generates laser beams, the receiver and photodetector receive reflected optical signals, the scanning mechanism scans the surrounding environment, and the angle resolver determines the position of target objects.</p><p>Based on scanning methods, LiDAR is categorized functionally into the following types:</p><ul><li><p><strong>Rotating LiDAR</strong>: Rotating LiDAR conducts an omnidirectional scan of the laser beam in the horizontal direction by rotating the emitter or scanning mechanism. These LiDAR sensors typically feature high scanning speeds and measurement accuracy, and they are widely applied in autonomous driving, 3D environmental modeling, and mapping.</p></li><li><p><strong>Solid-State LiDAR</strong>: Solid-state LiDAR utilizes solid-state laser emitters without requiring rotating components. These units are typically more compact, lighter, and consume less power. Solid-state LiDAR is suitable for application scenarios such as mobile devices, drones, and robots.</p></li><li><p><strong>Mechanical LiDAR</strong>: Mechanical LiDAR uses mechanical components, such as rotating mirrors or rotating prisms, to scan the laser beam. These units generally offer longer measurement ranges and high measurement accuracy, although their scanning speeds are slower. Mechanical LiDAR is widely used in topographic surveying, building scanning, and navigation.</p></li><li><p><strong>Phase-Modulated LiDAR</strong>: Phase-modulated LiDAR measures the distance between the target object and the sensor by modulating the phase of the laser beam. These sensors generally provide high measurement accuracy and wide measurement ranges, and they are broadly utilized in mapping, surveying, and industrial applications.</p></li><li><p><strong>Flash LiDAR</strong>: Flash LiDAR emits a brief, high-power laser pulse to illuminate the entire scene at once, and then captures the reflected optical signals through a detector array. Featuring high speed and high resolution, it is suitable for rapid scene capture and motion tracking applications.</p></li></ul><h2 id="_3-2-lidar-operating-principles-and-ranging-methods" tabindex="-1">3.2 LiDAR Operating Principles and Ranging Methods <a class="header-anchor" href="#_3-2-lidar-operating-principles-and-ranging-methods" aria-label="Permalink to &quot;3.2 LiDAR Operating Principles and Ranging Methods&quot;">​</a></h2><h3 id="_3-2-1-lidar-ranging" tabindex="-1">3.2.1 LiDAR Ranging <a class="header-anchor" href="#_3-2-1-lidar-ranging" aria-label="Permalink to &quot;3.2.1 LiDAR Ranging&quot;">​</a></h3><p>Common LiDAR systems determine the distance to a target using two primary ranging methods: triangulation and Time-of-Flight, or TOF, ranging.</p><p>The diagram below illustrates the principle of TOF ranging. The LiDAR emits a light pulse toward an object, which reflects the light directly back to the LiDAR receiver. The LiDAR calculates half of the round-trip travel time of the light and multiplies this duration by the speed of light to determine the distance between the object and the LiDAR.</p><img loading="lazy" height="323" width="836" src="'+o+'" class="common_img" style="width:600px;"><p>The diagram below illustrates the principle of triangulation ranging. During manufacturing, the LiDAR is calibrated so that the emitted beam is directed toward the object at a specific angle rather than projecting directly along the baseline. This angle is preset and remains constant during operation. The distance between the object and the LiDAR is calculated by substituting this angle and the baseline length into trigonometric functions.</p><img loading="lazy" height="341" width="834" src="'+r+'" class="common_img" style="width:600px;"><h3 id="_3-2-2-lidar-scanning-effect" tabindex="-1">3.2.2 LiDAR Scanning Effect <a class="header-anchor" href="#_3-2-2-lidar-scanning-effect" aria-label="Permalink to &quot;3.2.2 LiDAR Scanning Effect&quot;">​</a></h3><p>The diagram below illustrates the scanning effect of LiDAR. As the LiDAR emits light beams onto object surfaces and receives the reflected signals, it maps the coordinates of the illuminated points to outline the contours of surrounding objects.</p><img loading="lazy" height="572" width="813" src="'+l+'" class="common_img" style="width:600px;"><h2 id="_3-3-lidar-obstacle-avoidance" tabindex="-1">3.3 LiDAR Obstacle Avoidance <a class="header-anchor" href="#_3-3-lidar-obstacle-avoidance" aria-label="Permalink to &quot;3.3 LiDAR Obstacle Avoidance&quot;">​</a></h2><p>To learn how to connect the app, refer to <a href="https://drive.google.com/drive/folders/1fFo3fA72xG8UAcqcdB7UyhIA6pN2Gjrq?usp=sharing" target="_blank" rel="noreferrer">1.3.3 App Installation and Connection</a> under <a href="https://drive.google.com/drive/folders/1fFo3fA72xG8UAcqcdB7UyhIA6pN2Gjrq?usp=sharing" target="_blank" rel="noreferrer">1. Tutorials/1. JetHexa User Manual</a>.</p><h3 id="_3-3-1-enabling-via-app" tabindex="-1">3.3.1 Enabling via App <a class="header-anchor" href="#_3-3-1-enabling-via-app" aria-label="Permalink to &quot;3.3.1 Enabling via App&quot;">​</a></h3><ol><li><p>Launch the <strong>WonderAi</strong> app and connect to the JetHexa robot.</p></li><li><p>Tap <strong>Lidar</strong> on the mode selection screen to open its interface.</p></li></ol><img loading="lazy" height="865" width="1829" src="'+h+'" class="common_img" style="width:600px;"><ol start="3"><li>Tap the switch next to <strong>Avoid obstacle</strong> to enable the mode.</li></ol><img loading="lazy" height="1152" width="2560" src="'+d+'" class="common_img" style="width:600px;"><h3 id="_3-3-2-enabling-via-command-line" tabindex="-1">3.3.2 Enabling via Command Line <a class="header-anchor" href="#_3-3-2-enabling-via-command-line" aria-label="Permalink to &quot;3.3.2 Enabling via Command Line&quot;">​</a></h3><ol><li><p>Power on the robot and connect it to the remote desktop software <a href="https://drive.google.com/drive/folders/1fFo3fA72xG8UAcqcdB7UyhIA6pN2Gjrq?usp=sharing" target="_blank" rel="noreferrer">NoMachine</a>. For remote desktop connection details, refer to <a href="https://drive.google.com/drive/folders/1fFo3fA72xG8UAcqcdB7UyhIA6pN2Gjrq?usp=sharing" target="_blank" rel="noreferrer">1.4 Development Environment Setup</a> under <a href="https://drive.google.com/drive/folders/1fFo3fA72xG8UAcqcdB7UyhIA6pN2Gjrq?usp=sharing" target="_blank" rel="noreferrer">1. Tutorials/1. JetHexa User Manual</a>.</p></li><li><p>Click the <img loading="lazy" height="34" width="43" src="'+p+'" class="inline-icon"> icon on the desktop to open the terminal.</p></li><li><p>Enter the command to stop the auto-start service and press <strong>Enter</strong>:</p></li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">~</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">/.stop_ros.sh</span></span></code></pre></div><ol start="4"><li>Enter the following command and press <strong>Enter</strong> to launch the LiDAR node:</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ros2</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> launch</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> app</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lidar_node.launch.py</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> debug:=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span></code></pre></div><ol start="5"><li>Open a new terminal window, enter the following command, and press <strong>Enter</strong> to initialize the LiDAR application:</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ros2</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> service</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> call</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /lidar_app/enter</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> std_srvs/srv/Trigger</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> {}</span></span></code></pre></div><ol start="6"><li>In the current terminal window, enter the following command and press <strong>Enter</strong> to enable LiDAR obstacle avoidance:</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ros2</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> service</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> call</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /lidar_app/set_running</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> interfaces/srv/SetInt64</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;{data: 1}&quot;</span></span></code></pre></div><ol start="7"><li>To stop the current function, enter the following command in the current terminal window and press <strong>Enter</strong>:</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ros2</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> service</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> call</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /lidar_app/set_running</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> interfaces/srv/SetInt64</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;{data: 0}&quot;</span></span></code></pre></div><ol start="8"><li>To terminate the gameplay, press <strong>Ctrl+C</strong> in the terminal window from step 4.</li></ol><h3 id="_3-3-3-program-outcome" tabindex="-1">3.3.3 Program Outcome <a class="header-anchor" href="#_3-3-3-program-outcome" aria-label="Permalink to &quot;3.3.3 Program Outcome&quot;">​</a></h3><p>When using the LiDAR obstacle avoidance function, the target object must be taller than the horizontal scanning plane of the LiDAR so that the onboard sensor can effectively detect its position. The hexapod robot walks forward in a straight line. Upon detecting an obstacle, it automatically turns to bypass it.</p><h2 id="_3-4-lidar-following" tabindex="-1">3.4 LiDAR Following <a class="header-anchor" href="#_3-4-lidar-following" aria-label="Permalink to &quot;3.4 LiDAR Following&quot;">​</a></h2><p>To learn how to connect the app, refer to <a href="https://drive.google.com/drive/folders/1fFo3fA72xG8UAcqcdB7UyhIA6pN2Gjrq?usp=sharing" target="_blank" rel="noreferrer">1.3.3 App Installation and Connection</a> under <a href="https://drive.google.com/drive/folders/1fFo3fA72xG8UAcqcdB7UyhIA6pN2Gjrq?usp=sharing" target="_blank" rel="noreferrer">1. Tutorials/1. JetHexa User Manual</a>.</p><h3 id="_3-4-1-enabling-via-app" tabindex="-1">3.4.1 Enabling via App <a class="header-anchor" href="#_3-4-1-enabling-via-app" aria-label="Permalink to &quot;3.4.1 Enabling via App&quot;">​</a></h3><ol><li><p>Launch the <strong>WonderAi</strong> app and connect to the JetHexa robot.</p></li><li><p>Tap <strong>Lidar</strong> on the mode selection screen to open its interface.</p></li></ol><img loading="lazy" height="865" width="1829" src="'+g+'" class="common_img" style="width:600px;"><ol start="3"><li>Tap the switch next to <strong>Lidar following</strong> to enable the mode.</li></ol><img loading="lazy" height="1152" width="2560" src="'+c+'" class="common_img" style="width:600px;"><h3 id="_3-4-2-enabling-via-command-line" tabindex="-1">3.4.2 Enabling via Command Line <a class="header-anchor" href="#_3-4-2-enabling-via-command-line" aria-label="Permalink to &quot;3.4.2 Enabling via Command Line&quot;">​</a></h3><ol><li><p>Power on the robot and connect it to the remote desktop software <a href="https://drive.google.com/drive/folders/1fFo3fA72xG8UAcqcdB7UyhIA6pN2Gjrq?usp=sharing" target="_blank" rel="noreferrer">NoMachine</a>. For remote desktop connection details, refer to <a href="https://drive.google.com/drive/folders/1fFo3fA72xG8UAcqcdB7UyhIA6pN2Gjrq?usp=sharing" target="_blank" rel="noreferrer">1.4 Development Environment Setup</a> under <a href="https://drive.google.com/drive/folders/1fFo3fA72xG8UAcqcdB7UyhIA6pN2Gjrq?usp=sharing" target="_blank" rel="noreferrer">1. Tutorials/1. JetHexa User Manual</a>.</p></li><li><p>Click the <img loading="lazy" height="34" width="43" src="'+A+'" class="inline-icon"> icon on the desktop to open the terminal.</p></li><li><p>Enter the command to stop the auto-start service and press <strong>Enter</strong>:</p></li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">~</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">/.stop_ros.sh</span></span></code></pre></div><ol start="4"><li>Enter the following command and press <strong>Enter</strong> to launch the LiDAR node:</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ros2</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> launch</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> app</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lidar_node.launch.py</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> debug:=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span></code></pre></div><ol start="5"><li>Open a new terminal window, enter the following command, and press <strong>Enter</strong> to initialize the LiDAR application:</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ros2</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> service</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> call</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /lidar_app/enter</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> std_srvs/srv/Trigger</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> {}</span></span></code></pre></div><ol start="6"><li>In the current terminal window, enter the following command and press <strong>Enter</strong> to enable LiDAR following:</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ros2</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> service</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> call</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /lidar_app/set_running</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> interfaces/srv/SetInt64</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;{data: 2}&quot;</span></span></code></pre></div><ol start="7"><li>To stop the current function, enter the following command in the current terminal window and press <strong>Enter</strong>:</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ros2</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> service</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> call</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /lidar_app/set_running</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> interfaces/srv/SetInt64</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;{data: 0}&quot;</span></span></code></pre></div><ol start="8"><li>To terminate the gameplay, press <strong>Ctrl+C</strong> in the terminal window from step 4.</li></ol><h3 id="_3-4-3-program-outcome" tabindex="-1">3.4.3 Program Outcome <a class="header-anchor" href="#_3-4-3-program-outcome" aria-label="Permalink to &quot;3.4.3 Program Outcome&quot;">​</a></h3><p>When using the LiDAR following function, the target object must be taller than the horizontal scanning plane of the LiDAR so that the onboard sensor can effectively detect its position. The hexapod robot then adjusts its position to maintain a constant preset distance from the obstacle.</p><h2 id="_3-5-lidar-guarding" tabindex="-1">3.5 LiDAR Guarding <a class="header-anchor" href="#_3-5-lidar-guarding" aria-label="Permalink to &quot;3.5 LiDAR Guarding&quot;">​</a></h2><p>To learn how to connect the app, refer to <a href="https://drive.google.com/drive/folders/1fFo3fA72xG8UAcqcdB7UyhIA6pN2Gjrq?usp=sharing" target="_blank" rel="noreferrer">1.3.3 App Installation and Connection</a> under <a href="https://drive.google.com/drive/folders/1fFo3fA72xG8UAcqcdB7UyhIA6pN2Gjrq?usp=sharing" target="_blank" rel="noreferrer">1. Tutorials/1. JetHexa User Manual</a>.</p><h3 id="_3-5-1-enabling-via-app" tabindex="-1">3.5.1 Enabling via App <a class="header-anchor" href="#_3-5-1-enabling-via-app" aria-label="Permalink to &quot;3.5.1 Enabling via App&quot;">​</a></h3><ol><li><p>Launch the <strong>WonderAi</strong> app and connect to the JetHexa robot.</p></li><li><p>Tap <strong>Lidar</strong> on the mode selection screen to open its interface.</p></li></ol><img loading="lazy" height="865" width="1829" src="'+m+'" class="common_img" style="width:600px;"><ol start="3"><li>Tap the switch next to <strong>Lidar guarding</strong> to enable the mode.</li></ol><img loading="lazy" height="1152" width="2560" src="'+k+'" class="common_img" style="width:600px;"><h3 id="_3-5-2-enabling-via-command-line" tabindex="-1">3.5.2 Enabling via Command Line <a class="header-anchor" href="#_3-5-2-enabling-via-command-line" aria-label="Permalink to &quot;3.5.2 Enabling via Command Line&quot;">​</a></h3><ol><li><p>Power on the robot and connect it to the remote desktop software <a href="https://drive.google.com/drive/folders/1fFo3fA72xG8UAcqcdB7UyhIA6pN2Gjrq?usp=sharing" target="_blank" rel="noreferrer">NoMachine</a>. For remote desktop connection details, refer to <a href="https://drive.google.com/drive/folders/1fFo3fA72xG8UAcqcdB7UyhIA6pN2Gjrq?usp=sharing" target="_blank" rel="noreferrer">1.4 Development Environment Setup</a> under <a href="https://drive.google.com/drive/folders/1fFo3fA72xG8UAcqcdB7UyhIA6pN2Gjrq?usp=sharing" target="_blank" rel="noreferrer">1. Tutorials/1. JetHexa User Manual</a>.</p></li><li><p>Click the <img loading="lazy" height="34" width="43" src="'+u+'" class="inline-icon"> icon on the desktop to open the terminal.</p></li><li><p>Enter the command to stop the auto-start service and press <strong>Enter</strong>:</p></li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">~</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">/.stop_ros.sh</span></span></code></pre></div><ol start="4"><li>Enter the following command and press <strong>Enter</strong> to launch the LiDAR node:</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ros2</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> launch</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> app</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lidar_node.launch.py</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> debug:=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span></code></pre></div><ol start="5"><li>Open a new terminal window, enter the following command, and press <strong>Enter</strong> to initialize the LiDAR application:</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ros2</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> service</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> call</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /lidar_app/enter</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> std_srvs/srv/Trigger</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> {}</span></span></code></pre></div><ol start="6"><li>In the current terminal window, enter the following command and press <strong>Enter</strong> to enable LiDAR guarding:</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ros2</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> service</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> call</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /lidar_app/set_running</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> interfaces/srv/SetInt64</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;{data: 3}&quot;</span></span></code></pre></div><ol start="7"><li>To stop the current function, enter the following command in the current terminal window and press <strong>Enter</strong>:</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ros2</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> service</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> call</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /lidar_app/set_running</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> interfaces/srv/SetInt64</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;{data: 0}&quot;</span></span></code></pre></div><ol start="8"><li>To terminate the gameplay, press <strong>Ctrl+C</strong> in the terminal window from step 4.</li></ol><h3 id="_3-5-3-program-outcome" tabindex="-1">3.5.3 Program Outcome <a class="header-anchor" href="#_3-5-3-program-outcome" aria-label="Permalink to &quot;3.5.3 Program Outcome&quot;">​</a></h3><p>When using the LiDAR guarding function, the target object must be taller than the horizontal scanning plane of the LiDAR so that the onboard sensor can effectively detect its position. The hexapod robot then adjusts its body orientation to face directly toward the obstacle, aligning the camera with the target.</p>',83)])])}const w=a(f,[["render",b]]);export{D as __pageData,w as default};
